SELECT  json_build_object('aggregate', json_build_object('count', COUNT(*), 'sum', json_build_object('id', sum("_root"."root.pg.id" ) ), 'avg', json_build_object('id', avg("_root"."root.pg.id" ) ), 'min', json_build_object('id', min("_root"."root.pg.id" ) ), 'max', json_build_object('id', max("_root"."root.pg.id" ) ) ), 'nodes', coalesce(json_agg("root.f.nodes" ORDER BY "root.pg.id" DESC NULLS FIRST), '[]' ) ) AS "root" FROM  (SELECT  row_to_json((SELECT  "_e"  FROM  (SELECT  "_root.base"."id" AS "id", "_root.base"."name" AS "name", "_root.ar.nodes.articles"."articles" AS "articles"       ) AS "_e"      ) ) AS "root.f.nodes", "_root.base"."id" AS "root.pg.id" FROM  (SELECT  *  FROM "public"."author"  WHERE (("public"."author"."id") >= (('2')::integer))   ORDER BY "id" DESC NULLS FIRST LIMIT 3 OFFSET 1) AS "_root.base" LEFT OUTER JOIN LATERAL (SELECT  coalesce(json_agg("articles" ), '[]' ) AS "articles" FROM  (SELECT  row_to_json((SELECT  "_e"  FROM  (SELECT  "_root.ar.nodes.articles.base"."id" AS "id"       ) AS "_e"      ) ) AS "articles" FROM  (SELECT  *  FROM "public"."article"  WHERE (("_root.base"."id") = ("author_id"))     ) AS "_root.ar.nodes.articles.base"      ) AS "_root.ar.nodes.articles"      ) AS "_root.ar.nodes.articles" ON ('true')    ORDER BY "root.pg.id" DESC NULLS FIRST  ) AS "_root"
